WITH valid AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, is_remote, level, COALESCE(full_name, 'N/A') AS full_name_filled FROM employees WHERE manager_id IS NOT NULL), ranked AS (SELECT id, job_title, salary, full_name_filled FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, id ASC) = 1), latest AS (SELECT id, job_title, salary, full_name_filled FROM ranked QUALIFY ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary DESC, id ASC) = 1), cleaned AS (SELECT *, CAST(salary AS INT) AS salary_int, ROUND(salary * 1.07, 2) AS salary_scaled FROM latest WHERE job_title IS NOT NULL) SELECT CASE WHEN salary >= 155000 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_tier, SIZE(COLLECT_SET(job_title)) AS num_job_titles, PERCENTILE_APPROX(salary_scaled, ARRAY(0.25, 0.5, 0.75)) AS salary_scaled_quartiles, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles FROM cleaned GROUP BY CASE WHEN salary >= 155000 THEN 'PREMIUM' ELSE 'STANDARD' END;
